sql:
SELECT printf('%.4f', 100.0 * SUM(CASE WHEN atom.element = 'h' THEN 1 ELSE 0 END) / COUNT(atom.atom_id)) AS percentage
FROM atom
WHERE atom.molecule_id = 'TR206';

